void cgroup_migrate_add_src ( struct css_set * src_cset , struct cgroup * dst_cgrp , struct cgroup_mgctx * mgctx ) { struct cgroup * src_cgrp ; lockdep_assert_held ( & cgroup_mutex ) ; lockdep_assert_held ( & css_set_lock ) ; src_cgrp = cset_cgroup_from_root ( src_cset , dst_cgrp -> root ) ; if ( ! list_empty ( & src_cset -> mg_preload_node ) ) { return ; } WARN_ON ( src_cset -> mg_src_cgrp ) ; WARN_ON ( src_cset -> mg_dst_cgrp ) ; WARN_ON ( ! list_empty ( & src_cset -> mg_tasks ) ) ; WARN_ON ( ! list_empty ( & src_cset -> mg_node ) ) ; src_cset -> mg_src_cgrp = src_cgrp ; src_cset -> mg_dst_cgrp = dst_cgrp ; get_css_set ( src_cset ) ; list_add_tail ( & src_cset -> mg_preload_node , & mgctx -> preloaded_src_csets ) ; } 